package exercise
import ("errors";"fmt";"runtime/debug")
type Outcome struct {Err error; Panicked bool; Stack string; NeedsReconciliation bool}
func RunTask(fn func()error)(<-chan Outcome,error) {
 if fn==nil {return nil,errors.New("task function is required")}
 result:=make(chan Outcome,1)
 go func(){
  returned:=false;out:=Outcome{}
  defer func(){
   if !returned {value:=recover();out.Err=fmt.Errorf("task panic: %v",value);out.Panicked=true;out.Stack=string(debug.Stack());out.NeedsReconciliation=true}
   result<-out;close(result)
  }()
  out.Err=fn();returned=true
 }()
 return result,nil
}
```

原题知识说明：
保留panic栈并确认发生goroutine与recover所在栈不同；recover不能跨goroutine捕获。暂停依赖该worker的批量动作并核对未决副作用，由开发为任务入口定义同goroutine恢复边界，记录失败和堆栈并判断共享状态是否仍安全。验收worker panic返回明确失败且任务可对账；若状态可能损坏，应受控退出而非吞异常继续运行。

