package exercise
import("testing";"context";"os";"os/exec";"time";"strings";"errors";"sync/atomic")
func TestUnsafeChild(t *testing.T){
 if os.Getenv("OPSF_UNSAFE_WORKER")!="1"{return}
 defer func(){if recover()!=nil {os.Stdout.WriteString("CALLER_RECOVERED_CHILD")}}()
 go func(){panic("unsafe-worker-boom")}()
 select{}
}
func TestCallerRecoverCannotCatchWorker(t *testing.T){
 ctx,cancel:=context.WithTimeout(context.Background(),3*time.Second);defer cancel()
 cmd:=exec.CommandContext(ctx,os.Args[0],"-test.run=^TestUnsafeChild$")
 cmd.Env=append(os.Environ(),"OPSF_UNSAFE_WORKER=1")
 output,err:=cmd.CombinedOutput()
 if ctx.Err()!=nil||err==nil||!strings.Contains(string(output),"unsafe-worker-boom")||strings.Contains(string(output),"CALLER_RECOVERED_CHILD"){t.Fatal("child panic control not reproduced",err,string(output))}
 t.Log("NATIVE_GO_UNRECOVERED_WORKER_CHILD_EXIT_REPRODUCED")
}
func outcome(t *testing.T,fn func()error) Outcome {
 t.Helper();result,err:=RunTask(fn);if err!=nil||result==nil{t.Fatal("start",err)}
 if cap(result)!=1{t.Fatal("result must buffer exactly one outcome")}
 select {case value,ok:=<-result:
  if !ok{t.Fatal("no outcome")};select{case _,ok:=<-result:if ok{t.Fatal("extra outcome")};case <-time.After(time.Second):t.Fatal("result never closed")};return value
 case <-time.After(time.Second):t.Fatal("worker result deadline");return Outcome{}}
}
func TestTaskOutcomes(t *testing.T){
 if result,err:=RunTask(nil);result!=nil||err==nil{t.Fatal("nil must fail synchronously")}
 normal:=outcome(t,func()error{return nil});if normal.Err!=nil||normal.Panicked||normal.Stack!=""||normal.NeedsReconciliation{t.Fatal("success",normal)}
 sentinel:=errors.New("original task error");ordinary:=outcome(t,func()error{return sentinel})
 if !errors.Is(ordinary.Err,sentinel)||ordinary.Panicked||ordinary.Stack!=""||ordinary.NeedsReconciliation{t.Fatal("ordinary error",ordinary)}
 for _,value:=range []any{"worker-boom",nil}{
  var writes atomic.Int32
  failed:=outcome(t,func()error{writes.Add(1);panic(value)})
  if failed.Err==nil||!strings.Contains(failed.Err.Error(),"panic")||!failed.Panicked||!failed.NeedsReconciliation||!strings.Contains(failed.Stack,"goroutine")||writes.Load()!=1{t.Fatal("panic lost or task repeated",failed,writes.Load())}
 }
 // The process remains alive, and a fresh independent task still has explicit success.
 if later:=outcome(t,func()error{return nil});later.Err!=nil||later.Panicked{t.Fatal("later task",later)}
}
